void add_hostkey_file(char *s) {
    if (hostkey_count >= hostkey_cap) {
        hostkey_cap = hostkey_cap ? hostkey_cap*2 : 8;
        hostkey_files = realloc(hostkey_files, hostkey_cap*sizeof(char*));
    }
    hostkey_files[hostkey_count++] = s;
}
void add_port_arg(char *s) {
    if (port_count >= port_cap) {
        port_cap = port_cap ? port_cap*2 : 8;
        port_args = realloc(port_args, port_cap*sizeof(char*));
    }
    port_args[port_count++] = s;
}

// -p parsing, called immediately during CLI parsing for each -p arg
// on Bad port / Bad -p argument, logs and exits 1 immediately
// on "" segfaults
// else stores parsed spec for later listening
void parse_p_arg(char *arg) {
    // segfault on empty
    if (arg[0] == '\0') {
        // segfault like original (no output, SIGSEGV)
        volatile char *p = (volatile char*)0;
        *p = 0;
        // fallback
        abort();
    }
    char *addr = NULL;
    char *port = NULL;
    // need to dup? We'll store pointers into duplicated strings
    // For error messages, need to show port part (or full? see logic)
    // Logic deduced:
    // if starts with '[':
    //   find ']'
    //   if no ']': Bad address '<arg>' + Bad -p argument, exit
    //   else if after ']' is '\0': port = inside brackets (strip), addr=NULL? (treat as port)
    //   else if after ']' is ':': addr = inside (may be empty -> NULL?), port = after "]:", if port empty -> Bad port
    //   else: Bad address + Bad -p argument
    // else:
    //   find last ':'
    //   if no ':': addr=NULL, port=arg
    //   else: addr = before ':', port = after ':', if port empty -> Bad port
    //        if addr empty -> NULL (any)
    // For error reporting later (Failed listening...), need to know what to show:
    //  For address:port form (with colon, even if addr empty?), show port part only
    //  For no-colon, show full arg
    //  For bracketed without port ([abc]), show stripped inside as port? (full? Actually shows 'abc' without brackets)
    // We'll store addr/port accordingly, and also orig for Bad address messages
    if (arg[0] == '[') {
        char *close = strchr(arg, ']');
        if (!close) {
            log_msg("Bad address '%s'", arg);
            log_msg("Early exit: Bad -p argument");
            exit(1);
        }
        if (*(close+1) == '\0') {
            // [addr] with no port -> treat inside as port
            size_t inner_len = close - (arg+1);
            char *inner = malloc(inner_len+1);
            memcpy(inner, arg+1, inner_len);
            inner[inner_len]='\0';
            // addr NULL, port inner
            // store
            ports = realloc(ports, (nports+1)*sizeof(PortSpec));
            ports[nports].addr = NULL;
            ports[nports].port = inner;
            ports[nports].orig = strdup(arg);
            nports++;
            return;
        } else if (*(close+1) == ':') {
            // [addr]:port
            size_t inner_len = close - (arg+1);
            char *inner = malloc(inner_len+1);
            memcpy(inner, arg+1, inner_len);
            inner[inner_len]='\0';
            char *p = close+2; // after "]:"
            if (*p == '\0') {
                // Bad port
                log_msg("Early exit: Bad port");
                exit(1);
            }
            char *a = NULL;
            if (inner_len==0) {
                free(inner);
                a = NULL;
            } else {
                a = inner;
            }
            char *pp = strdup(p);
            ports = realloc(ports, (nports+1)*sizeof(PortSpec));
            ports[nports].addr = a;
            ports[nports].port = pp;
            ports[nports].orig = strdup(arg);
            nports++;
            return;
        } else {
            log_msg("Bad address '%s'", arg);
            log_msg("Early exit: Bad -p argument");
            exit(1);
        }
    } else {
        char *colon = strrchr(arg, ':');
        if (!colon) {
            // no colon: port = arg
            ports = realloc(ports, (nports+1)*sizeof(PortSpec));
            ports[nports].addr = NULL;
            ports[nports].port = strdup(arg);
            ports[nports].orig = strdup(arg);
            nports++;
            return;
        } else {
            // split
            char *p = colon+1;
            if (*p == '\0') {
                log_msg("Early exit: Bad port");
                exit(1);
            }
            size_t alen = colon - arg;
            char *a = NULL;
            if (alen==0) {
                a = NULL;
            } else {
                a = malloc(alen+1);
                memcpy(a, arg, alen);
                a[alen]='\0';
            }
            char *pp = strdup(p);
            ports = realloc(ports, (nports+1)*sizeof(PortSpec));
            ports[nports].addr = a;
            ports[nports].port = pp;
            ports[nports].orig = strdup(arg);
            nports++;
            return;
        }
    }
}

int is_flag_opt(char c) {
    // flags (no arg): R F e m w s g B t j k a i z V h
    // Note: t is flag? Actually -t is flag (2fa), -T takes arg. Need case sensitive.
    return (c=='R'||c=='F'||c=='e'||c=='m'||c=='w'||c=='s'||c=='g'||c=='B'||c=='t'||c=='j'||c=='k'||c=='a'||c=='i'||c=='z'||c=='V'||c=='h');
}
int is_arg_opt(char c) {
    return (c=='b'||c=='r'||c=='D'||c=='G'||c=='T'||c=='c'||c=='p'||c=='P'||c=='l'||c=='W'||c=='K'||c=='I');
}

void handle_opt(char opt, char *optarg) {
    // called during parsing, for valid opts (already checked missing)
    // for -p, parse immediately (may exit/segfault)
    // for others, store
    switch(opt) {
        case 'b': banner_file = optarg; break;
        case 'r': add_hostkey_file(optarg); break;
        case 'D': auth_dir = optarg; break;
        case 'G': opt_G = optarg; break;
        case 'T': opt_T_str = optarg; break;
        case 'c': forced_cmd = optarg; break;
        case 'p': add_port_arg(optarg); parse_p_arg(optarg); break;
        case 'P': pidfile = optarg; break;
        case 'l': iface = optarg; break;
        case 'W': opt_W_str = optarg; break;
        case 'K': opt_K_str = optarg; break;
        case 'I': opt_I_str = optarg; break;
        case 'R': opt_R = 1; break;
        case 'F': opt_F = 1; break;
        case 'e': opt_e = 1; break;
        case 'm': opt_m = 1; break;
        case 'w': opt_w = 1; break;
        case 's': opt_s = 1; break;
        case 'g': opt_g = 1; break;
        case 'B': opt_B = 1; break;
