    const char *strs[10] = {KEX_ALGOS, HOSTKEY_ALGOS, ENC_ALGOS, ENC_ALGOS, MAC_ALGOS, MAC_ALGOS, COMP_C2S, COMP_S2C, "", ""};
    size_t payload_len = 1+16+1+4; // msg+cookie+first+reserved
    for (int i=0;i<10;i++) payload_len += 4 + strlen(strs[i]);
