    p[0]=(v>>24)&0xFF; p[1]=(v>>16)&0xFF; p[2]=(v>>8)&0xFF; p[3]=v&0xFF;
}
uint32_t get_u32(unsigned char *p) {
    return ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|(uint32_t)p[3];
}

// build KEXINIT packet (returns malloced buf with 4-byte len included, *out_len set)
unsigned char *build_kexinit(size_t *out_len) {
    // payload: msg 20 (1) + cookie 16 + 10 strings + first_follows (1) + reserved (4)
    const char *strs[10] = {KEX_ALGOS, HOSTKEY_ALGOS, ENC_ALGOS, ENC_ALGOS, MAC_ALGOS, MAC_ALGOS, COMP_C2S, COMP_S2C, "", ""};
    size_t payload_len = 1+16+1+4; // msg+cookie+first+reserved
    for (int i=0;i<10;i++) payload_len += 4 + strlen(strs[i]);
    // packet: 1 (padlen) + payload_len + padlen, total+4 %8==0, padlen>=4
    size_t base = 1 + payload_len;
    size_t padlen = 8 - ((base+4)%8);
    if (padlen<4) padlen+=8;
    size_t packet_len = base + padlen; // this is value in len field (excludes 4-byte len itself)
    size_t total = 4 + packet_len; // includes len field
    unsigned char *buf = malloc(total);
    put_u32(buf, (uint32_t)packet_len);
    buf[4]=(unsigned char)padlen;
    size_t pos=5;
    buf[pos++]=20; // SSH2_MSG_KEXINIT
    get_random_bytes(buf+pos, 16);
    pos+=16;
    for (int i=0;i<10;i++) {
        size_t l=strlen(strs[i]);
        put_u32(buf+pos, (uint32_t)l);
        pos+=4;
        memcpy(buf+pos, strs[i], l);
        pos+=l;
    }
    buf[pos++]=0; // first follows
    put_u32(buf+pos, 0);
    pos+=4;
    // padding random
    get_random_bytes(buf+pos, padlen);
    pos+=padlen;
    *out_len=total;
    return buf;
}

// check if algo negotiation succeeds: client_list (comma separated) vs server_list
// returns 1 if common found, 0 if not. If common, sets *negotiated to first client algo that is in server list? Actually SSH picks first client algo that server supports.
// For our purposes, just need to know if any common.
int has_common_algo(const char *client, const char *server) {
    // split client by ',', check if any token equals any server token
    // server split too
    // Note: empty? If client empty? Then no match? Probably.
    if (!client || !server) return 0;
    // quick: if client empty string, no match
    if (client[0]=='\0') return 0;
    // Use temporary copies
    char *c_copy = strdup(client);
    char *s_copy = strdup(server);
    // split server into array
    // Instead of array, for each client token, check if in server list via strstr with boundaries?
    // Simpler: for each client token, check if server contains it as whole token (comma-separated)
    int found=0;
    char *save1=NULL, *save2=NULL;
    // Build server tokens list? We'll just for each client token, search in server string with token boundaries.
    // To avoid O(n^2) with many, fine (small lists).
    char *ctok = strtok_r(c_copy, ",", &save1);
    while (ctok) {
        // check if ctok in server list
        char *s_copy2 = strdup(server);
        char *stok = strtok_r(s_copy2, ",", &save2);
        while (stok) {
            if (strcmp(ctok, stok)==0) { found=1; break; }
            stok=strtok_r(NULL, ",", &save2);
        }
        free(s_copy2);
        if (found) break;
        ctok=strtok_r(NULL, ",", &save1);
    }
    free(c_copy);
    free(s_copy);
    return found;
}
// get negotiated algo (first client that server supports), returns malloced string or NULL
char *get_negotiated(const char *client, const char *server) {
    if (!client || !server || client[0]=='\0') return NULL;
    char *c_copy=strdup(client);
    char *save1=NULL;
    char *ctok=strtok_r(c_copy, ",", &save1);
    while (ctok) {
        // check in server
        char *s_copy=strdup(server);
        char *save2=NULL;
        char *stok=strtok_r(s_copy, ",", &save2);
        while (stok) {
            if (strcmp(ctok,stok)==0) {
                char *res=strdup(ctok);
                free(s_copy);
                free(c_copy);
                return res;
            }
            stok=strtok_r(NULL, ",", &save2);
        }
        free(s_copy);
        ctok=strtok_r(NULL, ",", &save1);
    }
    free(c_copy);
    return NULL;
}
