// connection handling utilities
ssize_t read_n(int fd, void *buf, size_t n, int timeout_sec) {
    // read exactly n bytes, with timeout (for idle timeout? Actually idle timeout is for whole connection? We'll handle idle via select with timeout.)
    // If timeout_sec <0, block indefinitely. If >=0, use select with timeout.
    // Returns n on success, 0 on EOF (peer closed before n), -1 on error/timeout? For timeout, return -2? Let's distinguish.
    size_t off=0;
    unsigned char *p=buf;
    while (off<n) {
        if (timeout_sec>=0) {
            fd_set rfds;
            FD_ZERO(&rfds);
            FD_SET(fd, &rfds);
            struct timeval tv;
            tv.tv_sec=timeout_sec;
            tv.tv_usec=0;
            // For idle timeout, need to handle that timeout is desde last activity? Our caller will manage.
            // Use select
            int r=select(fd+1, &rfds, NULL, NULL, &tv);
            if (r==0) return -2; // timeout
            if (r<0) {
                if (errno==EINTR) continue;
                return -1;
            }
        }
        ssize_t r=read(fd, p+off, n-off);
        if (r==0) {
            // EOF
            if (off==0) return 0;
            else return off; // partial? Caller should handle? Actually for packet reading, if EOF before n, treat as disconnect (Exited normally). Return 0?
            // To simplify, return 0 to indicate EOF
            return 0;
        }
        if (r<0) {
            if (errno==EINTR) continue;
            return -1;
        }
        off+=r;
    }
    return n;
}

// write all
int write_all(int fd, void *buf, size_t n) {
    size_t off=0;
    unsigned char *p=buf;
    while (off<n) {
        ssize_t r=write(fd, p+off, n-off);
        if (r<=0) {
            if (r<0 && errno==EINTR) continue;
            return -1;
        }
        off+=r;
    }
    return 0;
}

